        let validSource = false;
        let sourceName = "";
        let sourceAPI = "";

        for (let i = 0; i < data.length; i++) {
            if (data[i][1] === sourceType) {
                validSource = true;
                sourceName = data[i][0];
                sourceAPI = data[i][2];
                break;
            }
        }

        if (validSource) {
            var variable = {
                sourceType: sourceType,
